CREATE TRIGGER ledger_lines_valid_insert
      BEFORE INSERT ON ledger_lines
      WHEN NEW.debit_minor < 0
        OR NEW.credit_minor < 0
        OR (NEW.debit_minor > 0 AND NEW.credit_minor > 0)
      BEGIN SELECT RAISE(ABORT, 'Invalid ledger line values'); END;
CREATE TRIGGER ledger_lines_valid_update
      BEFORE UPDATE OF debit_minor, credit_minor ON ledger_lines
      WHEN NEW.debit_minor < 0
        OR NEW.credit_minor < 0
        OR (NEW.debit_minor > 0 AND NEW.credit_minor > 0)
      BEGIN SELECT RAISE(ABORT, 'Invalid ledger line values'); END;
CREATE TRIGGER migration_baseline_delete BEFORE DELETE ON migration_baselines BEGIN SELECT RAISE(ABORT,'Historical baseline is immutable'); END;
CREATE TRIGGER migration_baseline_replace BEFORE INSERT ON migration_baselines WHEN EXISTS(SELECT 1 FROM migration_baselines WHERE key=NEW.key) BEGIN SELECT RAISE(ABORT,'Historical baseline is immutable'); END;
